def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    for r in range(h - 1):
        for c in range(w - 1):
            if not all(grid[y][x] == 2 for y in (r, r + 1) for x in (c, c + 1)):
                continue

            positions = {
                "nw": (r - 1, c - 1),
                "ne": (r - 1, c + 2),
                "sw": (r + 2, c - 1),
                "se": (r + 2, c + 2),
            }
            markers = {}
            for key, (y, x) in positions.items():
                if 0 <= y < h and 0 <= x < w and grid[y][x] != 0:
                    markers[key] = grid[y][x]

            rays = [
                (positions["nw"], -1, -1, markers.get("sw")),
                (positions["ne"], -1, 1, markers.get("nw")),
                (positions["sw"], 1, -1, markers.get("se")),
                (positions["se"], 1, 1, markers.get("ne")),
            ]
            for (y, x), dy, dx, color in rays:
                if color is None:
                    continue
                while 0 <= y < h and 0 <= x < w:
                    out[y][x] = color
                    y += dy
                    x += dx

    return out
