def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    original = [row[:] for row in grid]

    for r in range(h - 1):
        for c in range(w - 1):
            if not all(original[y][x] == 2
                       for y in (r, r + 1) for x in (c, c + 1)):
                continue

            rays = [
                (r - 1, c - 1, -1, -1, original[r + 2][c - 1]),
                (r - 1, c + 2, -1,  1, original[r - 1][c - 1]),
                (r + 2, c - 1,  1, -1, original[r + 2][c + 2]),
                (r + 2, c + 2,  1,  1, original[r - 1][c + 2]),
            ]

            for y, x, dy, dx, color in rays:
                if color == 0:
                    continue
                first = True
                while 0 <= y < h and 0 <= x < w:
                    if not first and original[y][x] != 0:
                        break
                    out[y][x] = color
                    first = False
                    y += dy
                    x += dx

    return out
